export function slugify(s: string): string {
	return s.toLowerCase().replace(/\s+/g, '-');
}

export function truncate(s: string, n: number): string {
	const keep = Math.max(0, n);
	if (s.length <= keep) return s;
	return s.slice(0, keep) + '...';
}

